INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM225UU38', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 8 - 3x$. What is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$25$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 5$: $g(5) = 8 - 3(5) = 8 - 15 = -7$. The value $7$ results from computing $|8 - 15|$, incorrectly dropping the negative sign. The value $25$ comes from computing $(8 - 3)(5) = 25$, subtracting the coefficient from the constant first and then multiplying by 5. The value $23$ results from computing $8 + 15 = 23$, adding instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2287LDV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the product of the solutions to the equation $x^2 - 9x + 14 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$9$"},{"key":"C","text":"$-14$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring: $x^2 - 9x + 14 = (x - 2)(x - 7) = 0$, so $x = 2$ and $x = 7$. The product is $2 \\times 7 = 14$. Alternatively, by Vieta''s formulas the product of the roots of $x^2 + bx + c = 0$ equals $c$, which is $14$. The value $9$ confuses the product with the sum of the roots. The value $-14$ introduces an incorrect negative sign. The value $-9$ confuses the product with the negation of the coefficient of $x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22GAWU9', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$3x + 2y = 23$ and $x - 2y = -3$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $(3x + 2y) + (x - 2y) = 23 + (-3)$, which gives $4x = 20$, so $x = 5$. The value $4$ results from an arithmetic slip such as dividing $20$ by $5$ instead of $4$. The value $-5$ introduces a sign error when dividing. The value $20$ is the result of $4x = 20$ before dividing by $4$, stopping one step early.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22VDI3G', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7x^2 - 21x$?', NULL, $lyceon_json$[{"key":"A","text":"$7x(x - 3)$"},{"key":"B","text":"$7x(x + 3)$"},{"key":"C","text":"$x(7x - 3)$"},{"key":"D","text":"$7(x^2 - 3)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring out the greatest common factor of $7x$ from $7x^2 - 21x$ gives $7x(x - 3)$. The option $7x(x + 3)$ uses the wrong sign inside the parentheses, since $7x \\cdot (+3) = 21x$, not $-21x$. The option $x(7x - 3)$ incorrectly factors out only $x$ and changes the coefficient from $21$ to $3$. The option $7(x^2 - 3)$ factors out $7$ but drops the $x$ from the second term, yielding $7x^2 - 21$ instead of $7x^2 - 21x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM235A512', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $p$ is defined such that $p(a) = b$ and $p(b) = a$, where $a \\neq b$. If $a = 13$ and $b = -5$, what is the value of $p(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$8$"},{"key":"C","text":"$-4$"},{"key":"D","text":"$\\frac{13}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function passes through $(13, -5)$ and $(-5, 13)$. The slope is $\\frac{13 - (-5)}{-5 - 13} = \\frac{18}{-18} = -1$. Using point $(13, -5)$: $p(x) = -(x - 13) + (-5) = -x + 13 - 5 = -x + 8$. Therefore $p(0) = 8$. The value 4 results from computing the midpoint of 13 and $-5$, confusing the average of $a$ and $b$ with the function value. The value $-4$ comes from a sign error when evaluating $-0 + 8$ as $-(0 + 8) + 4$. The value $\\frac{13}{2}$ comes from halving $a$ without constructing the linear function.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23AWYS1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A bookstore initially priced a textbook at $\\$47$. After a first markup of $20\\%$, the store later applied a discount of $15\\%$ to the marked-up price. What is the final price of the textbook, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$49.35$"},{"key":"B","text":"$\\$47.00$"},{"key":"C","text":"$\\$47.94$"},{"key":"D","text":"$\\$54.99$"}]$lyceon_json$::jsonb, 'C', NULL, E'The marked-up price is $47 \\times 1.20 = \\$56.40$. The discounted price is $56.40 \\times 0.85 = \\$47.94$. The value $\\$49.35$ comes from computing a net $5\\%$ increase on $\\$47$ directly ($47 \\times 1.05 = 49.35$) rather than applying the two percentage changes sequentially to different bases. The value $\\$47.00$ reflects the misconception that a $20\\%$ increase followed by a $15\\%$ decrease returns to the original price, which is false because the $15\\%$ discount applies to the higher marked-up amount. The value $\\$54.99$ results from applying the $15\\%$ discount only to the markup amount ($\\$56.40 - \\$47 = \\$9.40$) instead of the full marked-up price, yielding $\\$56.40 - 0.15 \\times 9.40 = \\$56.40 - \\$1.41 = \\$54.99$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23DV6PQ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A parking garage charges a flat fee of $\\$4$ plus $\\$3$ per hour. A driver has at most $\\$22$ to spend on parking. Which inequality represents the number of hours $h$ the driver can park?', NULL, $lyceon_json$[{"key":"A","text":"$3h + 4 \\leq 22$"},{"key":"B","text":"$3h + 4 \\geq 22$"},{"key":"C","text":"$4h + 3 \\leq 22$"},{"key":"D","text":"$3h - 4 \\leq 22$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of $\\$4$ plus $\\$3$ per hour, giving $3h + 4$. Since the driver has at most $\\$22$, the cost must be less than or equal to $22$, yielding $3h + 4 \\leq 22$. The option $3h + 4 \\geq 22$ reverses the direction of the inequality, incorrectly requiring the driver to spend at least $\\$22$. The option $4h + 3 \\leq 22$ swaps the per-hour rate and the flat fee. The option $3h - 4 \\leq 22$ subtracts the flat fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23V1IZY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $PQR$, angle $Q$ is the right angle. If $\\cos P = \\frac{9}{41}$ and $QR = 40k$ for some positive value $k$, what is the area of triangle $PQR$ in terms of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$180k$"},{"key":"B","text":"$180k^2$"},{"key":"C","text":"$360k^2$"},{"key":"D","text":"$820k^2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $\\cos P = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{9}{41}$, the side lengths follow the $9$-$40$-$41$ Pythagorean triple (since $9^2 + 40^2 = 81 + 1600 = 1681 = 41^2$). The side opposite $P$ is $QR = 40k$, so the scale factor is $k$ and the adjacent side $PQ = 9k$. The area is $\\frac{1}{2}(PQ)(QR) = \\frac{1}{2}(9k)(40k) = 180k^2$. The value $180k$ neglects that both legs carry the factor $k$, so the product includes $k^2$. The value $360k^2$ omits the $\\frac{1}{2}$ factor. The value $820k^2$ incorrectly uses the hypotenuse $41k$ in place of the leg $9k$, computing $\\frac{1}{2}(41k)(40k)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24J33NH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one of the acute angles is $\\theta$, where $\\sin \\theta = \\frac{5}{13}$. If the side opposite $\\theta$ has length $10$, what is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{50}{13}$"},{"key":"B","text":"$24$"},{"key":"C","text":"$26$"},{"key":"D","text":"$34$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin \\theta = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{5}{13}$, the triangle has a $5$-$12$-$13$ ratio. The opposite side is $10$, so the scale factor is $\\frac{10}{5} = 2$. The hypotenuse is $13 \\times 2 = 26$. The value $\\frac{50}{13}$ results from inverting the ratio and computing $\\frac{10 \\times 5}{13}$. The value $24$ is the adjacent side ($12 \\times 2$), not the hypotenuse. The value $34$ results from adding $10 + 24$ instead of using the ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24N6O8U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A printer produces 23 pages per minute. How many minutes will it take to print 391 pages?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Dividing the total number of pages by the rate gives $\\frac{391}{23} = 17$ minutes. The rate is 23 pages per minute, so the time required is found by dividing the total pages by the per-minute rate.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24ZXOWU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In a triangle, one exterior angle measures $131^\\circ$. One of the two non-adjacent interior angles measures $54^\\circ$. What is the measure, in degrees, of the other non-adjacent interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$49$"},{"key":"B","text":"$77$"},{"key":"C","text":"$108$"},{"key":"D","text":"$131$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $131 = 54 + x$, which gives $x = 131 - 54 = 77$ degrees. The value $49$ comes from computing $180 - 131 = 49$, which is the adjacent interior angle, not the requested one. The value $108$ comes from incorrectly doubling $54$. The value $131$ mistakes the exterior angle itself for the missing interior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25MLD9D', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $\\frac{x}{3} + 7 = 12$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$5$"},{"key":"C","text":"$\\frac{19}{3}$"},{"key":"D","text":"$57$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtract 7 from both sides: $\\frac{x}{3} = 5$. Multiply both sides by 3: $x = 15$. The value $5$ results from finding $\\frac{x}{3} = 5$ but stopping without multiplying by 3. The value $\\frac{19}{3}$ comes from adding 7 to 12 to get 19 and then dividing by 3, reversing the subtraction step. The value $57$ results from computing $(12 + 7) \\times 3 = 57$, adding instead of subtracting before multiplying.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26CJIW9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A colony of algae in a research tank has a population modeled by $P(t) = 850 \\cdot 2^{t/6}$, where $t$ is the number of days since the study began. By what factor does the population increase from day $12$ to day $30$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'C', NULL, E'The growth factor from day $12$ to day $30$ is $\\frac{P(30)}{P(12)} = \\frac{850 \\cdot 2^{30/6}}{850 \\cdot 2^{12/6}} = \\frac{2^5}{2^2} = 2^{5-2} = 2^3 = 8$. The coefficient $850$ cancels. The value $3$ mistakes the exponent difference ($5 - 2 = 3$) for the factor itself, confusing the exponent with the result. The value $6$ comes from an arithmetic error such as computing the day difference $30 - 12 = 18$ and dividing by $3$ instead of using the exponential ratio. The value $32$ equals $2^5$, which is the total growth factor from $t = 0$ to $t = 30$, not the factor over the interval from day $12$ to day $30$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27OL9BX', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'If $3(2x - 7) > 4x + 11$, what is the least integer value of $x$ that satisfies the inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Distribute on the left side: $6x - 21 > 4x + 11$. Subtract $4x$ from both sides: $2x - 21 > 11$. Add $21$ to both sides: $2x > 32$. Divide both sides by $2$: $x > 16$. Since $x$ must be strictly greater than $16$, the least integer satisfying the inequality is $17$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27TRYQW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $6$ and a central angle of $150^\\circ$. What is the area of the sector formed by this central angle?', NULL, $lyceon_json$[{"key":"A","text":"$5\\pi$"},{"key":"B","text":"$15\\pi$"},{"key":"C","text":"$30\\pi$"},{"key":"D","text":"$36\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{\\theta}{360} \\times \\pi r^2$. Substituting gives $\\frac{150}{360} \\times \\pi(6)^2 = \\frac{5}{12} \\times 36\\pi = 15\\pi$. The value $5\\pi$ results from using the arc-length-related formula $\\frac{\\theta}{360} \\times 2\\pi r$ and misinterpreting it as area, giving $\\frac{5}{12} \\times 12\\pi = 5\\pi$. The value $30\\pi$ results from using $\\frac{150}{180}$ instead of $\\frac{150}{360}$. The value $36\\pi$ is the area of the full circle, ignoring the fraction determined by the central angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27U1IZU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A ceramics studio uses $\\frac{7}{4}$ pounds of clay to produce 3 identical bowls. At this rate, how many pounds of clay are needed to produce 54 bowls?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{2}$"},{"key":"B","text":"$\\frac{63}{2}$"},{"key":"C","text":"$\\frac{189}{4}$"},{"key":"D","text":"$\\frac{378}{4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of clay per bowl is $\\frac{7}{4} \\div 3 = \\frac{7}{12}$ pounds per bowl. For 54 bowls: $\\frac{7}{12} \\times 54 = \\frac{378}{12} = \\frac{63}{2}$, which equals $31.5$ pounds. The value $\\frac{7}{2}$ results from dividing $\\frac{7}{4}$ by $\\frac{1}{2}$ instead of scaling up, only partially reasoning through the proportion. The value $\\frac{189}{4}$ results from multiplying $\\frac{7}{4}$ by $27$ instead of $18$, an arithmetic error in computing the scale factor $\\frac{54}{3}$. The value $\\frac{378}{4}$ results from multiplying $\\frac{7}{4}$ directly by $54$ without dividing by the 3-bowl group size first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2832IGA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A storage container shaped like a rectangular prism has a length of $23$ inches, a width of $11$ inches, and a height of $9$ inches. What is the volume, in cubic inches, of the container?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2277', ARRAY['2277'], E'The volume of a rectangular prism is found by multiplying length, width, and height: $23 \\times 11 \\times 9$. First, $23 \\times 11 = 253$. Then $253 \\times 9 = 2277$. The volume is $2277$ cubic inches.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM294R26P', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $c$ does the system $y = 2x^2 + 5x + c$ and $y = x - 3$ have exactly one solution?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $2x^2 + 5x + c = x - 3$, which gives $2x^2 + 4x + (c + 3) = 0$. For exactly one solution, the discriminant must equal zero: $4^2 - 4(2)(c + 3) = 0$, so $16 - 8(c + 3) = 0$, meaning $16 - 8c - 24 = 0$, thus $-8c = 8$ and $c = -1$. The value $1$ results from a sign error when solving $-8c = 8$, getting $c = 1$ instead of $c = -1$. The value $-5$ comes from incorrectly rearranging the original equation, omitting the constant $-3$ from the right side. The value $5$ results from computing the discriminant as $16 + 8(c + 3)$ with an incorrect sign, then solving.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AH0JET', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'The expression $\\frac{x^2 - 11x + 28}{x - 4}$ is equivalent to which of the following, for $x \\neq 4$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 7$"},{"key":"B","text":"$x - 7$"},{"key":"C","text":"$x - 4$"},{"key":"D","text":"$x + 4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator: $x^2 - 11x + 28 = (x - 4)(x - 7)$, since $(-4)(-7) = 28$ and $(-4) + (-7) = -11$. Dividing by $(x - 4)$ leaves $x - 7$. The option $x + 7$ uses the wrong sign for $7$, as though the factored form were $(x - 4)(x + 7)$, which would expand to $x^2 + 3x - 28$. The option $x - 4$ confuses the cancelled factor with the remaining one. The option $x + 4$ does not correspond to any correct factorization of the numerator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B7LUNB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'The equation $3x + 7y = 84$ represents a line in the $xy$-plane. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'At the $x$-intercept, $y = 0$. Substituting into $3x + 7(0) = 84$ gives $3x = 84$. Dividing both sides by 3 yields $x = 28$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BSYJUE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution to the equation $x^2 - 81 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$81$"},{"key":"D","text":"$40.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The equation $x^2 = 81$ has solutions $x = 9$ and $x = -9$. Since the question asks for the positive solution, the answer is $9$. The value $-9$ is a valid solution but is negative, not positive. The value $81$ comes from forgetting to take the square root. The value $40.5$ results from dividing $81$ by $2$ instead of taking its square root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQZYNG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 400 registered voters in a city found that $58\\%$ support a proposed parks initiative. The margin of error for the survey is $\\pm 4$ percentage points at $95\\%$ confidence. Which of the following is the best conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all registered voters in the city support the initiative."},{"key":"B","text":"It is plausible that between $54\\%$ and $62\\%$ of all registered voters in the city support the initiative."},{"key":"C","text":"Between $54\\%$ and $62\\%$ of all residents in the city support the initiative."},{"key":"D","text":"The probability that a randomly selected voter supports the initiative is $0.58$."}]$lyceon_json$::jsonb, 'B', NULL, E'A $95\\%$ confidence interval of $58\\% \\pm 4\\%$ means it is plausible that the true proportion of all registered voters who support the initiative lies between $54\\%$ and $62\\%$, which is correctly stated. Claiming that exactly $58\\%$ support the initiative confuses a sample statistic with the population parameter and ignores the margin of error. Extending the conclusion to all residents of the city overgeneralizes beyond the surveyed population of registered voters. Stating that the probability for a randomly selected voter is $0.58$ confuses a population proportion estimate with an individual probability and ignores the margin of error entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DSGH11', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A theater sells adult tickets for $\\$11$ each and child tickets for $\\$7$ each. On a particular evening, $53$ tickets were sold for a total of $\\$471$. How many adult tickets were sold?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'Let $a$ represent the number of adult tickets and $c$ represent the number of child tickets. The system is $a + c = 53$ and $11a + 7c = 471$. From the first equation, $c = 53 - a$. Substituting into the second equation: $11a + 7(53 - a) = 471$. Distributing: $11a + 371 - 7a = 471$. Combining like terms: $4a + 371 = 471$. Subtracting $371$: $4a = 100$. Dividing by $4$: $a = 25$. Therefore $25$ adult tickets were sold.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F1FIVM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 7 \\cdot 3^x$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$81$"},{"key":"B","text":"$84$"},{"key":"C","text":"$448$"},{"key":"D","text":"$567$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = 4$ into $f(x) = 7 \\cdot 3^x$ gives $f(4) = 7 \\cdot 3^4 = 7 \\cdot 81 = 567$. The value $81$ results from computing $3^4$ but omitting the coefficient $7$. The value $84$ results from incorrectly multiplying the base and exponent ($7 \\cdot 3 \\cdot 4 = 84$) instead of applying exponentiation. The value $448$ results from swapping the base and exponent to get $7 \\cdot 4^3 = 7 \\cdot 64 = 448$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F7OUMY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'If $4x + 3y = 31$ and $2x - 3y = -7$, what is the value of $x + y$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$4$"},{"key":"C","text":"$9$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations: $(4x + 3y) + (2x - 3y) = 31 + (-7)$, giving $6x = 24$ and $x = 4$. Substituting into $2x - 3y = -7$: $8 - 3y = -7$, so $-3y = -15$ and $y = 5$. Therefore $x + y = 4 + 5 = 9$. The value $1$ comes from computing $x - y = 4 - 5$ instead of $x + y$. The value $4$ is just $x$ alone, stopping before finding $y$. The value $13$ arises from incorrectly solving for $x + 2y$ instead of $x + y$, for example by misreading the coefficient structure of the original equations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FBEOHB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'A quadratic function $f$ has its vertex at $(4, -9)$ and passes through the point $(1, 18)$. The function can be written in the form $f(x) = a(x - 4)^2 - 9$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Using the vertex form $f(x) = a(x - 4)^2 - 9$ and the condition $f(1) = 18$, substitute $x = 1$: $a(1 - 4)^2 - 9 = 18$, which gives $a(-3)^2 - 9 = 18$, so $9a - 9 = 18$. Adding $9$ to both sides yields $9a = 27$, and dividing by $9$ gives $a = 3$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGSS8Y', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A food truck sells each burrito for $\\$8.50$ and has fixed daily costs of $\\$119$. The owner wants to earn a daily profit of more than $\\$204$. Which inequality represents the number of burritos $b$ the owner must sell each day to meet this goal?', NULL, $lyceon_json$[{"key":"A","text":"$8.50b + 119 > 204$"},{"key":"B","text":"$8.50b - 119 > 204$"},{"key":"C","text":"$8.50(b - 119) > 204$"},{"key":"D","text":"$8.50b > 119$"}]$lyceon_json$::jsonb, 'B', NULL, E'Profit equals revenue minus costs. Revenue from $b$ burritos is $8.50b$, and fixed costs are $\\$119$, so profit is $8.50b - 119$. The owner wants profit greater than $\\$204$, giving $8.50b - 119 > 204$. The option $8.50b + 119 > 204$ adds costs to revenue instead of subtracting them. The option $8.50(b - 119) > 204$ incorrectly applies the per-burrito price to a quantity reduced by the cost figure, conflating units. The option $8.50b > 119$ only ensures revenue exceeds costs but ignores the $\\$204$ profit target entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HXK5DW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylindrical water tank has a radius of $7$ centimeters and a height of $13$ centimeters. What is the volume, in cubic centimeters, of the tank?', NULL, $lyceon_json$[{"key":"A","text":"$91\\pi$"},{"key":"B","text":"$182\\pi$"},{"key":"C","text":"$637\\pi$"},{"key":"D","text":"$1274\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 7$ and $h = 13$ gives $V = \\pi(7)^2(13) = \\pi(49)(13) = 637\\pi$ cubic centimeters. The value $91\\pi$ results from forgetting to square the radius and computing $\\pi(7)(13)$. The value $182\\pi$ results from using the lateral-surface-area formula $2\\pi r h$ instead of the volume formula. The value $1274\\pi$ results from incorrectly doubling $637\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IK903K', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $a = \\frac{\\sqrt{50} + \\sqrt{18}}{\\sqrt{2}}$, what is the value of $a^2$?', NULL, $lyceon_json$[{"key":"A","text":"$64$"},{"key":"B","text":"$68$"},{"key":"C","text":"$34$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'A', NULL, E'Simplify $\\sqrt{50} = 5\\sqrt{2}$ and $\\sqrt{18} = 3\\sqrt{2}$. Then $a = \\frac{5\\sqrt{2} + 3\\sqrt{2}}{\\sqrt{2}} = \\frac{8\\sqrt{2}}{\\sqrt{2}} = 8$. Therefore $a^2 = 64$. The value $68$ comes from incorrectly simplifying $\\sqrt{18}$ as $4\\sqrt{2}$ instead of $3\\sqrt{2}$, giving $a = 9$ and then miscomputing $9^2$ as $68$. The value $34$ results from adding $25 + 9 = 34$ by squaring the coefficients $5$ and $3$ separately instead of first adding them. The value $32$ comes from computing $a = 4\\sqrt{2}$ by incorrectly halving the sum $8$, then squaring to get $32$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2INOMEL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the points $(2, 11)$ and $(6, 31)$. What is the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$\\frac{1}{5}$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{31 - 11}{6 - 2} = \\frac{20}{4} = 5$. The value 4 comes from miscalculating the numerator as 16 instead of 20. The value $\\frac{1}{5}$ results from inverting the slope formula to run over rise instead of rise over run. The value 20 is the numerator alone without dividing by the change in $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JR6IUC', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $(3x - 7)(2x + 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 + 13x - 63$"},{"key":"B","text":"$6x^2 - 13x - 63$"},{"key":"C","text":"$6x^2 + 27x - 63$"},{"key":"D","text":"$6x^2 + 13x + 63$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using FOIL: $(3x)(2x) = 6x^2$, $(3x)(9) = 27x$, $(-7)(2x) = -14x$, and $(-7)(9) = -63$. Combining like terms: $27x - 14x = 13x$, giving $6x^2 + 13x - 63$. The option $6x^2 - 13x - 63$ reverses the sign of the middle term, treating $-14x + 27x$ as $-(27x - 14x)$. The option $6x^2 + 27x - 63$ uses only the outer product $27x$ and drops the inner product $-14x$. The option $6x^2 + 13x + 63$ has the correct middle term but incorrectly makes the constant positive, missing that $(-7)(9) = -63$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JRVADC', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A baker makes croissants and muffins for a morning sale. Each croissant uses $6$ ounces of butter, and each muffin uses $2$ ounces. The baker has at most $174$ ounces of butter and wants to prepare at least $39$ items in total. If $c$ represents the number of croissants and $m$ represents the number of muffins, which system of inequalities best models this situation, where $c \\geq 0$ and $m \\geq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$6c + 2m \\leq 174$ and $c + m \\geq 39$"},{"key":"B","text":"$6c + 2m \\geq 174$ and $c + m \\leq 39$"},{"key":"C","text":"$2c + 6m \\leq 174$ and $c + m \\geq 39$"},{"key":"D","text":"$6c + 2m \\leq 174$ and $c + m \\leq 39$"}]$lyceon_json$::jsonb, 'A', NULL, E'The butter constraint is $6c + 2m \\leq 174$ because each croissant uses $6$ ounces, each muffin uses $2$ ounces, and the baker has at most $174$ ounces. The production goal is $c + m \\geq 39$ because the baker wants at least $39$ items. The option with both inequalities reversed ($6c + 2m \\geq 174$ and $c + m \\leq 39$) contradicts the problem: it requires using at least all the butter while making at most $39$ items. The option $2c + 6m \\leq 174$ swaps the butter usage per item, assigning $6$ ounces to muffins and $2$ to croissants. The option with $c + m \\leq 39$ in the second inequality misreads the at-least-$39$ requirement as an upper bound.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KYMC8H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A researcher recorded the number of minutes 9 participants spent on a puzzle: 11, 14, 17, 17, 19, 22, 23, 26, 31. If the value 31 is replaced by 58, which of the following measures changes?', NULL, $lyceon_json$[{"key":"A","text":"Mean only"},{"key":"B","text":"Median only"},{"key":"C","text":"Both mean and median"},{"key":"D","text":"Neither mean nor median"}]$lyceon_json$::jsonb, 'A', NULL, E'The data set has 9 values, so the median is the 5th value when ordered, which is 19 in both the original and modified sets. Replacing 31 with 58 increases the sum from 180 to 207, changing the mean from 20 to 23. Therefore the mean changes but the median does not. Selecting the median only reflects a misunderstanding of how the median is determined in an odd-count ordered data set. Selecting both mean and median incorrectly assumes that changing an extreme value always shifts the median. Selecting neither incorrectly assumes that replacing one value with another has no effect on the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LTX5AL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If the expression $\\frac{4x^6 y^{10}}{(2x^3 y^5)^2}$ can be simplified to a single constant $k$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1', ARRAY['1'], E'First expand the denominator: $(2x^3 y^5)^2 = 4x^6 y^{10}$. Then $\\frac{4x^6 y^{10}}{4x^6 y^{10}} = 1$. The expression simplifies to the constant $1$ because the numerator and denominator are identical after applying the power rule.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LVXOGE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A biologist modeled the relationship between the age $x$, in weeks, and the length $y$, in centimeters, of a certain fish species using the equation $y = 0.37x + 4.1$. What is the best interpretation of the slope in this context?', NULL, $lyceon_json$[{"key":"A","text":"The predicted increase in length, in centimeters, for each additional week of age"},{"key":"B","text":"The predicted length, in centimeters, of a fish that is 0 weeks old"},{"key":"C","text":"The predicted age, in weeks, when a fish reaches 4.1 centimeters"},{"key":"D","text":"The predicted total length, in centimeters, of a fish that is 1 week old"}]$lyceon_json$::jsonb, 'A', NULL, E'In the linear model $y = 0.37x + 4.1$, the slope $0.37$ represents the predicted change in the response variable $y$ (length in centimeters) for each one-unit increase in the explanatory variable $x$ (age in weeks). The predicted increase in length per additional week of age correctly identifies this meaning. The predicted length at 0 weeks old describes the $y$-intercept ($4.1$), not the slope. The predicted age when a fish reaches 4.1 centimeters confuses the roles of slope and intercept and reverses the variables. The predicted total length at 1 week old conflates the slope with the full model output at $x = 1$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LZ2P7Z', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The line $5x - 2y = k$ passes through the point $(-3, 13)$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-41$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$41$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $(-3, 13)$ into $5x - 2y = k$ gives $5(-3) - 2(13) = -15 - 26 = -41$. So $k = -41$. The value $-11$ results from computing $-15 + 26$, adding instead of subtracting. The value 41 comes from taking the absolute value and dropping the negative sign. The value 11 results from computing $26 - 15$ while ignoring the signs entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MHEB9N', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'If $\\frac{5}{2a - 3} = \\frac{8}{3a + 1}$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$-29$"},{"key":"B","text":"$\\frac{19}{9}$"},{"key":"C","text":"$29$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'C', NULL, E'Cross-multiplying gives $5(3a + 1) = 8(2a - 3)$. Expanding: $15a + 5 = 16a - 24$. Subtracting $15a$ from both sides: $5 = a - 24$. Adding 24 to both sides: $a = 29$. The value $-29$ results from a sign error when moving terms across the equation. The value $\\frac{19}{9}$ comes from an arithmetic slip such as incorrectly combining terms. The value 31 results from an error in expanding $8(2a - 3)$ as $16a - 16$ instead of $16a - 24$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MQ8W5I', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'A radioactive sample has a mass, in grams, modeled by the function $A(t) = 200 \\cdot \\left(\\frac{1}{2}\\right)^{t/5}$, where $t$ is the time in years. What is the mass, in grams, of the sample after $15$ years?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'Substituting $t = 15$ into $A(t) = 200 \\cdot \\left(\\frac{1}{2}\\right)^{t/5}$ gives $A(15) = 200 \\cdot \\left(\\frac{1}{2}\\right)^{15/5} = 200 \\cdot \\left(\\frac{1}{2}\\right)^3 = 200 \\cdot \\frac{1}{8} = 25$ grams. The exponent simplifies to $3$ because $15 \\div 5 = 3$, meaning the sample undergoes three half-lives in $15$ years.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NFWZNM', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{3(2x - 5)}{4} + 11 = 29$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14.5', ARRAY['29/2', '14.5'], E'Subtract 11 from both sides: $\\frac{3(2x - 5)}{4} = 18$. Multiply both sides by 4: $3(2x - 5) = 72$. Divide both sides by 3: $2x - 5 = 24$. Add 5 to both sides: $2x = 29$. Divide by 2: $x = 14.5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NTCIP8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(t) = -3t^2 + 14t - 11$. As $t$ increases without bound, which of the following best describes the behavior of $h(t)$?', NULL, $lyceon_json$[{"key":"A","text":"$h(t)$ increases without bound"},{"key":"B","text":"$h(t)$ decreases without bound"},{"key":"C","text":"$h(t)$ approaches $0$"},{"key":"D","text":"$h(t)$ approaches $-11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The leading term of $h(t)$ is $-3t^2$, which has a negative coefficient. For a quadratic with a negative leading coefficient, as $t$ increases without bound, the $-3t^2$ term dominates and drives the output toward negative infinity, so $h(t)$ decreases without bound. The claim that $h(t)$ increases without bound ignores the negative sign of the leading coefficient. The claim that $h(t)$ approaches $0$ confuses this quadratic with a decaying function. The claim that $h(t)$ approaches $-11$ mistakes the constant term for a horizontal asymptote, which quadratics do not have.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OEOSGW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 2x^2 - 28x + 103$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$14$"},{"key":"D","text":"$103$"}]$lyceon_json$::jsonb, 'A', NULL, E'To find the minimum value of $g(x) = 2x^2 - 28x + 103$, first locate the vertex. The $x$-coordinate of the vertex is $x = \\frac{-(-28)}{2(2)} = \\frac{28}{4} = 7$. Substituting into $g$: $g(7) = 2(49) - 28(7) + 103 = 98 - 196 + 103 = 5$. The minimum value is $5$. The value $7$ is the $x$-coordinate of the vertex, not the minimum output. The value $14$ confuses the coefficient of $x$ (halved) with the answer. The value $103$ is the $y$-intercept $g(0)$, not the minimum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q149OV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'grid_in', E'In a triangle, two of the interior angles have measures of $47^\\circ$ and $68^\\circ$. What is the measure, in degrees, of the third interior angle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '65', ARRAY['65'], E'The sum of the interior angles of any triangle is $180^\\circ$. The third angle measures $180 - 47 - 68 = 65$ degrees.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R2MAU3', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{2x}{x + 5} + \\frac{3}{x - 2}$ for $x \\neq -5$ and $x \\neq 2$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2x^2 - x + 15}{(x + 5)(x - 2)}$"},{"key":"B","text":"$\\frac{2x^2 + x + 15}{(x + 5)(x - 2)}$"},{"key":"C","text":"$\\frac{2x^2 + 15}{(x + 5)(x - 2)}$"},{"key":"D","text":"$\\frac{2x^2 - x - 15}{(x + 5)(x - 2)}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The common denominator is $(x + 5)(x - 2)$. Rewriting: $\\frac{2x(x - 2) + 3(x + 5)}{(x + 5)(x - 2)} = \\frac{2x^2 - 4x + 3x + 15}{(x + 5)(x - 2)} = \\frac{2x^2 - x + 15}{(x + 5)(x - 2)}$. The option $\\frac{2x^2 + x + 15}{(x + 5)(x - 2)}$ incorrectly computes $-4x + 3x$ as $+x$ instead of $-x$. The option $\\frac{2x^2 + 15}{(x + 5)(x - 2)}$ drops the linear terms entirely after combining. The option $\\frac{2x^2 - x - 15}{(x + 5)(x - 2)}$ has the correct linear coefficient but flips the sign of the constant, computing $3(x + 5)$ as $3x - 15$ instead of $3x + 15$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RGMR2Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher examined hospital records and found that patients who regularly consumed green tea had lower rates of a certain heart condition than patients who did not. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"There is an association between green tea consumption and lower rates of the heart condition."},{"key":"B","text":"Green tea consumption causes a reduction in the heart condition."},{"key":"C","text":"Patients who do not consume green tea will develop the heart condition."},{"key":"D","text":"The heart condition can be prevented by consuming green tea regularly."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researcher examined existing hospital records rather than randomly assigning patients to treatment and control groups, this is an observational study. Observational studies can identify associations but cannot establish causation, since confounding variables may explain the observed difference. Stating there is an association is the appropriate conclusion. Claiming that green tea causes a reduction in the heart condition incorrectly draws a causal conclusion from an observational study. Stating that patients who do not consume green tea will develop the condition makes an absolute prediction unsupported by the data. Stating the condition can be prevented by regular consumption also implies causation and overstates the findings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RVDK1K', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid metal cylinder has a radius of $5$ centimeters and a height of $18$ centimeters. A cone with the same base radius and the same height is carved out of the cylinder. What is the volume, in cubic centimeters, of the remaining metal?', NULL, $lyceon_json$[{"key":"A","text":"$150\\pi$"},{"key":"B","text":"$300\\pi$"},{"key":"C","text":"$450\\pi$"},{"key":"D","text":"$600\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of the cylinder is $\\pi r^2 h = \\pi(5)^2(18) = 450\\pi$. The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(25)(18) = 150\\pi$. The remaining volume is $450\\pi - 150\\pi = 300\\pi$ cubic centimeters. The value $150\\pi$ is only the cone volume, not the remaining metal. The value $450\\pi$ is only the cylinder volume before removal. The value $600\\pi$ results from adding the two volumes instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RVSA7A', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the value of $x$ if $\\sqrt{5x + 11} = 6$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Square both sides to get $5x + 11 = 36$. Then $5x = 25$, so $x = 5$. Checking: $\\sqrt{5(5) + 11} = \\sqrt{36} = 6$, which confirms the solution.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TATKG3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In 2023, a factory produced 1,400 units of a product. In 2024, production increased by $15\\%$ over 2023. In 2025, production decreased by $d\\%$ from the 2024 level, resulting in 1,449 units. What is the value of $d$?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$8$"},{"key":"C","text":"$12$"},{"key":"D","text":"$3.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'In 2024, production was $1{,}400 \\times 1.15 = 1{,}610$ units. After a decrease of $d\\%$ in 2025, the production is $1{,}610 \\times (1 - \\frac{d}{100}) = 1{,}449$. Solving: $1 - \\frac{d}{100} = \\frac{1{,}449}{1{,}610} = 0.90$, so $\\frac{d}{100} = 0.10$ and $d = 10$. The value $8$ results from an arithmetic error in computing the 2024 production level. The value $12$ comes from setting up the equation with the wrong base, applying the percentage decrease to the original 2023 production instead of the 2024 level. The value $3.5$ comes from computing the net change relative to the original 2023 level ($1{,}449 - 1{,}400 = 49$, then $\\frac{49}{1{,}400} \\approx 3.5\\%$), which confuses the net percent change with the 2025 decrease rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TPTJVK', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'Line $p$ has the equation $9x - 4y = 36$. Line $q$ is perpendicular to line $p$ and passes through the point $(0, 7)$. Which of the following is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$y = -\\frac{4}{9}x + 7$"},{"key":"B","text":"$y = \\frac{9}{4}x + 7$"},{"key":"C","text":"$y = \\frac{4}{9}x + 7$"},{"key":"D","text":"$y = -\\frac{9}{4}x + 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $9x - 4y = 36$ in slope-intercept form: $-4y = -9x + 36$, so $y = \\frac{9}{4}x - 9$. The slope of line $p$ is $\\frac{9}{4}$. A perpendicular line has slope equal to the negative reciprocal: $-\\frac{4}{9}$. Using the point $(0, 7)$, the equation is $y = -\\frac{4}{9}x + 7$. The equation $y = \\frac{9}{4}x + 7$ uses the original slope, which gives a parallel line. The equation $y = \\frac{4}{9}x + 7$ takes the reciprocal but omits the sign change. The equation $y = -\\frac{9}{4}x + 7$ negates the original slope without taking the reciprocal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U12UC3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive value of $x$ if $3x^2 = 75$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Divide both sides by $3$ to get $x^2 = 25$. Taking the positive square root gives $x = 5$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UIWQZK', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A linear function $h$ satisfies $h(3) = 17$ and $h(11) = 53$. What is the value of $h(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3.5', ARRAY['7/2', '3.5'], E'The slope is $\\frac{53 - 17}{11 - 3} = \\frac{36}{8} = 4.5$. Using the point $(3, 17)$: $h(x) = 4.5(x - 3) + 17 = 4.5x - 13.5 + 17 = 4.5x + 3.5$. Therefore $h(0) = 4.5(0) + 3.5 = 3.5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VQREE2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The equation $\\frac{3}{x - 2} + \\frac{5}{x + 4} = \\frac{2x}{(x - 2)(x + 4)}$ has how many valid solutions?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"Infinitely many"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiply both sides by $(x - 2)(x + 4)$: $3(x + 4) + 5(x - 2) = 2x$. Expanding: $3x + 12 + 5x - 10 = 2x$, so $8x + 2 = 2x$, giving $6x = -2$ and $x = -\\frac{1}{3}$. Since $x = -\\frac{1}{3}$ does not equal $2$ or $-4$, it does not create a zero denominator, so it is a valid solution. Thus there is exactly $1$ valid solution. The answer $0$ would apply only if the algebraic solution were an excluded value such as $2$ or $-4$. The answer $2$ incorrectly assumes that a rational equation with two distinct denominators always yields two solutions. The answer of infinitely many would apply only to an identity, which this equation is not.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W17WAN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a group of 200 concertgoers, 74 prefer jazz, 89 prefer classical, and 37 prefer folk. Of those who prefer jazz, $\\frac{2}{37}$ also play an instrument. Of those who prefer classical, $\\frac{9}{89}$ also play an instrument. Of those who prefer folk, $\\frac{6}{37}$ also play an instrument. If a concertgoer is selected at random from those who play an instrument, what is the probability that this person prefers classical?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{89}$"},{"key":"B","text":"$\\frac{9}{19}$"},{"key":"C","text":"$\\frac{9}{200}$"},{"key":"D","text":"$\\frac{89}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The number of instrument players in each genre is: jazz $74 \\times \\frac{2}{37} = 4$, classical $89 \\times \\frac{9}{89} = 9$, and folk $37 \\times \\frac{6}{37} = 6$. The total number of instrument players is $4 + 9 + 6 = 19$. Among these, 9 prefer classical, so the probability is $\\frac{9}{19}$. The value $\\frac{9}{89}$ is the probability that a classical fan plays an instrument, which reverses the conditional probability. The value $\\frac{9}{200}$ divides the classical instrument players by the total number of concertgoers instead of the total instrument players, confusing joint probability with conditional probability. The value $\\frac{89}{200}$ gives the proportion of all concertgoers who prefer classical, ignoring the instrument-playing condition entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WV5NCI', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $\\frac{18a^5 b^3}{6a^2 b}$?', NULL, $lyceon_json$[{"key":"A","text":"$3a^3 b^3$"},{"key":"B","text":"$12a^3 b^2$"},{"key":"C","text":"$3a^3 b^2$"},{"key":"D","text":"$3a^7 b^4$"}]$lyceon_json$::jsonb, 'C', NULL, E'Dividing coefficients gives $\\frac{18}{6} = 3$. For the variables, subtract exponents: $a^{5-2} = a^3$ and $b^{3-1} = b^2$, so the result is $3a^3 b^2$. The option $3a^3 b^3$ correctly simplifies everything except the $b$ exponent, keeping $b^3$ instead of subtracting. The option $12a^3 b^2$ subtracts the coefficients ($18 - 6 = 12$) instead of dividing. The option $3a^7 b^4$ adds exponents instead of subtracting them, which is the rule for multiplication, not division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X1UIE2', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $ax + 8y = 29$ and $15x - 24y = -87$ has infinitely many solutions. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$15$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'D', NULL, E'For infinitely many solutions, the two equations must be proportional. Dividing the second equation by $-3$: $\\frac{15}{-3}x - \\frac{24}{-3}y = \\frac{-87}{-3}$, which simplifies to $-5x + 8y = 29$. Comparing with $ax + 8y = 29$, the coefficients of $y$ and the constants already match, so $a = -5$. The value $5$ neglects the negative sign when dividing $15$ by $-3$. The value $-3$ is the scaling factor itself rather than the resulting coefficient. The value $15$ copies the coefficient of $x$ from the second equation without recognizing that proportionality requires scaling.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XTN8J7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The rational function $f$ is defined by $f(x) = \\frac{3x + 7}{x - 2}$. As $x$ increases without bound, what value does $f(x)$ approach?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{7}{3}$"},{"key":"B","text":"$2$"},{"key":"C","text":"$3$"},{"key":"D","text":"$\\frac{7}{2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'For the rational function $f(x) = \\frac{3x + 7}{x - 2}$, as $x$ grows large, the lower-order terms ($7$ in the numerator and $-2$ in the denominator) become negligible relative to the leading terms. The function approaches $\\frac{3x}{x} = 3$. The value $-\\frac{7}{3}$ incorrectly uses the ratio of the constants with a sign error. The value $2$ confuses the vertical asymptote location ($x = 2$) with the horizontal asymptote. The value $\\frac{7}{2}$ incorrectly takes the ratio of the constant terms from numerator and denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XXH39V', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A mechanic charges a flat fee of $\\$37$ plus $\\$19$ per hour of labor. If the total bill for a repair was $\\$170.50$, how many hours of labor were required?', NULL, $lyceon_json$[{"key":"A","text":"$6.5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$7.03$"},{"key":"D","text":"$8.97$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting up the equation $37 + 19h = 170.50$, subtract 37 from both sides to get $19h = 133.50$. Dividing both sides by 19 gives $h = 7$. The value 6.5 comes from rounding or an arithmetic slip during division. The value 7.03 results from dividing 133.50 by 19 with a calculation error. The value 8.97 comes from dividing 170.50 by 19 without first subtracting the flat fee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YTFQ85', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $y = 2x + 1$ and $y = x^2 - 3x + 5$, what is the sum of all $x$-values where these equations intersect?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $2x + 1 = x^2 - 3x + 5$, which rearranges to $x^2 - 5x + 4 = 0$. By Vieta''s formulas, the sum of the roots is $\\frac{-(-5)}{1} = 5$. Alternatively, factoring gives $(x - 1)(x - 4) = 0$, so $x = 1$ and $x = 4$, and $1 + 4 = 5$. The value $4$ comes from finding only the larger root and reporting it as the sum. The value $-5$ results from a sign error when applying Vieta''s formulas, using $-5$ instead of $+5$. The value $1$ confuses one of the individual roots with the sum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YZE55G', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A swimming pool is being drained at a constant rate. At $t = 0$ hours, the pool contains 4,700 gallons of water. After 3 hours, it contains 2,540 gallons. Which function $g(t)$ models the gallons of water remaining after $t$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$g(t) = 4700 - 720t$"},{"key":"B","text":"$g(t) = 4700 + 720t$"},{"key":"C","text":"$g(t) = 2540 - 720t$"},{"key":"D","text":"$g(t) = 4700 - 847t$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is $\\frac{2540 - 4700}{3} = \\frac{-2160}{3} = -720$ gallons per hour. With initial value 4,700, the function is $g(t) = 4700 - 720t$. The function $g(t) = 4700 + 720t$ uses a positive rate, implying the pool is filling. The function $g(t) = 2540 - 720t$ incorrectly uses the 3-hour value as the initial amount. The function $g(t) = 4700 - 847t$ results from dividing 2540 by 3 instead of computing the difference first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z21AZK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation $x^2 + y^2 - 14x + 6y + 33 = 0$ defines a circle in the $xy$-plane. What is the length of the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{5}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$\\sqrt{33}$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Rewrite the equation by completing the square. Group the $x$-terms and $y$-terms: $(x^2 - 14x) + (y^2 + 6y) = -33$. Complete the square for each: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = -33 + 49 + 9$, which simplifies to $(x - 7)^2 + (y + 3)^2 = 25$. Since the standard form is $(x - h)^2 + (y - k)^2 = r^2$, the radius squared is $25$, so the radius is $5$. The value $\\sqrt{5}$ results from incorrectly taking $\\sqrt{\\sqrt{25}}$. The value $\\sqrt{33}$ results from taking the square root of the original constant term without completing the square. The value $25$ confuses $r^2$ with $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZTR7TD', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'In the $xy$-plane, line $m$ passes through $(1, -2)$ and $(4, 7)$. Line $n$ passes through $(-5, 3)$ and is parallel to line $m$. What is the $y$-intercept of line $n$?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$-12$"},{"key":"C","text":"$13$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of line $m$ is $\\frac{7 - (-2)}{4 - 1} = \\frac{9}{3} = 3$. Since line $n$ is parallel, it also has slope 3. Using point $(-5, 3)$: $y - 3 = 3(x + 5)$, so $y = 3x + 15 + 3 = 3x + 18$. The $y$-intercept is 18. The value $-12$ results from computing $3 - 15$ instead of $3 + 15$ due to a sign error with the $x$-coordinate. The value 13 comes from using an incorrect slope of 2. The value $-7$ comes from using only one point incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22PTAII', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the overall structure of the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research since Thomas Hunt Morgan''s laboratory experiments in the early twentieth century. Its short generation time, large number of offspring, and well-mapped genome make it an ideal model organism. Recently, however, researchers have begun questioning whether findings from Drosophila studies translate reliably to human biology, given the vast evolutionary distance between insects and mammals.', $lyceon_json$[{"key":"A","text":"It introduces a widely used research subject, explains the reasons for its prominence, and then presents a challenge to its continued usefulness."},{"key":"B","text":"It compares two competing model organisms used in genetics research and argues that one is superior to the other."},{"key":"C","text":"It traces the complete historical development of genetics from Morgan's era to the present day."},{"key":"D","text":"It describes a laboratory procedure and then evaluates the statistical validity of the results obtained."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first introduces Drosophila as a staple of genetics research, then explains why it is ideal (short generation time, many offspring, well-mapped genome), and finally raises a concern about whether its findings translate to human biology. The option describing an introduction, explanation of prominence, and a challenge to usefulness accurately captures this three-part structure. The option about comparing two competing model organisms is wrong because the passage discusses only Drosophila, not a second organism. The option about tracing the complete historical development of genetics overstates the scope; the passage mentions Morgan''s work briefly but does not survey the history of genetics. The option about describing a laboratory procedure and evaluating statistical validity is wrong because the passage never describes a specific procedure or discusses statistics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23E5HL2', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason the researchers revised their initial model of diatom sinking rates?', E'Oceanographers studying phytoplankton dynamics in the Labrador Sea had long relied on a model predicting that diatoms sink at a relatively uniform rate once their silica-based frustules reach a critical mass. However, a 2021 expedition led by Tomas Lindqvist revealed that diatom sinking rates varied by as much as a factor of seven within the same water column. Lindqvist''s team discovered that certain diatom species secrete a polysaccharide coating that dramatically increases drag, slowing their descent regardless of frustule mass. This coating, which the researchers termed "viscous sheathing," appears to be triggered by low iron concentrations in the surrounding water. The finding prompted the team to revise the sinking-rate model to incorporate biological drag alongside the purely physical variable of frustule mass.', $lyceon_json$[{"key":"A","text":"Frustule mass had been measured inaccurately in earlier expeditions to the Labrador Sea."},{"key":"B","text":"Iron concentrations in the Labrador Sea were found to be significantly higher than previous surveys had indicated."},{"key":"C","text":"A biological mechanism that increases drag on sinking diatoms was discovered to affect descent speed independently of frustule mass."},{"key":"D","text":"The polysaccharide coating on diatom frustules was shown to increase sinking speed by reducing friction with surrounding water molecules."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage states that the researchers revised their model because they discovered a polysaccharide coating (viscous sheathing) that increases drag and slows diatom descent independently of frustule mass. The option identifying this biological drag mechanism as the reason for model revision directly captures that stated detail. The option about inaccurate frustule measurements is unsupported; the passage does not question the accuracy of earlier mass measurements. The option about higher iron concentrations reverses the passage''s point, which describes low iron concentrations triggering the coating. The option claiming the coating increases sinking speed contradicts the passage, which says the coating increases drag and slows descent.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2418RN2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In 1987, economists Raj Patel and Susan Lindqvist proposed that small-scale textile cooperatives in rural Guatemala could compete with factory-produced garments by emphasizing artisanal craftsmanship. Their prediction proved largely accurate: several cooperatives established during that period now export handwoven fabrics to international markets. ______ the cooperatives that survived did so not primarily through craftsmanship branding, as Patel and Lindqvist expected, but through adopting e-commerce platforms that gave them direct access to overseas buyers.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"For instance,"},{"key":"C","text":"However,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first affirms that the cooperatives succeeded, then reveals that the mechanism of success differed from the economists'' prediction. ''However,'' correctly signals this partial contrast: the outcome matched the prediction, but the reason did not. ''In other words,'' would indicate a restatement, but the final sentence introduces new and contrasting information rather than rephrasing the previous claim. ''For instance,'' would introduce an example supporting the prior statement, yet the final sentence qualifies it. ''Similarly,'' would signal agreement or parallel, which contradicts the shift in reasoning the final sentence presents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24UEAY0', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In a 2019 study of sediment cores extracted from Lake Ohrid on the border of Albania and North Macedonia, geochemists found that volcanic tephra layers from eruptions occurring over 1.4 million years ago had been remarkably well preserved, a finding that ______ earlier assumptions that such ancient deposits would have been chemically altered beyond recognition by prolonged interaction with groundwater.', $lyceon_json$[{"key":"A","text":"substantiated through independent verification"},{"key":"B","text":"confounded"},{"key":"C","text":"reiterated"},{"key":"D","text":"commemorated"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that ancient tephra layers were remarkably well preserved, contradicting the assumption that they would have been chemically altered beyond recognition. "Confounded" means to prove wrong or contradict expectations, which precisely captures how the finding undermined earlier assumptions. "Substantiated through independent verification" means to confirm with additional evidence, which is the opposite of what the passage describes since the finding contradicts, not confirms, the earlier assumptions. "Reiterated" means to say or do again, which implies restating the same assumptions rather than overturning them. "Commemorated" means to honor the memory of something, which is nonsensical when applied to scientific assumptions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
