INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW288HMM4', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student wants to present a paradox in how audiences experience Makinen''s compositional method. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A1HTRP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the coral reefs near Pulau Sipadan observed that certain species of parrotfish displayed a remarkable ability to ______ the chemical composition of algae before consuming it, allowing them to avoid toxic varieties that could impair their digestion.', $lyceon_json$[{"key":"A","text":"discern"},{"key":"B","text":"fabricate"},{"key":"C","text":"displace"},{"key":"D","text":"announce"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes parrotfish detecting the chemical composition of algae to avoid toxic ones. "Discern" means to perceive or recognize something, which fits the context of identifying chemical properties. "Fabricate" means to construct or invent, which is incoherent in the context of sensing chemical composition. "Displace" means to move something from its position, which does not relate to detecting properties. "Announce" means to make a public declaration, which makes no sense applied to a fish perceiving algae chemistry.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D734M9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The ethnomusicologist Fumiko Hayashi argued that the pentatonic scales found in traditional Okinawan folk songs are not merely remnants of an older musical tradition but instead represent a deliberate aesthetic choice that performers actively ______ through improvisational techniques passed down across generations.', $lyceon_json$[{"key":"A","text":"perpetuate"},{"key":"B","text":"demolish"},{"key":"C","text":"quarantine"},{"key":"D","text":"adjudicate between competing versions of"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that pentatonic scales represent a deliberate aesthetic choice maintained through improvisational techniques across generations. "Perpetuate" means to cause something to continue indefinitely, which precisely matches the idea of actively sustaining a tradition through practice. "Demolish" means to destroy completely, which contradicts the passage''s point that performers preserve these scales. "Quarantine" means to isolate to prevent spread of disease, which is incoherent when applied to a musical tradition. "Adjudicate between competing versions of" introduces a concept of judging between alternatives that the passage never suggests; the passage frames the scales as a unified choice, not a contested one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FGBKIU', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'What can most reasonably be inferred from the text?', E'When ecologist Priya Nagarajan introduced predatory beetles into greenhouse plots overrun by aphids, she expected the beetle population to stabilize once aphid numbers declined. Instead, the beetles began consuming each other at a high rate once aphid density dropped below a certain threshold. Nagarajan noted that this intraguild predation intensified when the remaining aphids clustered on the undersides of leaves, making them harder for the beetles to locate.', $lyceon_json$[{"key":"A","text":"The beetles turned to intraguild predation partly because their preferred prey became less accessible, not solely because prey numbers declined."},{"key":"B","text":"Beetles are generally more effective predators than aphids at avoiding being consumed in greenhouse environments."},{"key":"C","text":"Nagarajan's experiment demonstrated that predatory beetles cannot survive without a constant supply of aphids."},{"key":"D","text":"The aphids deliberately moved to the undersides of leaves in order to provoke intraguild predation among the beetles."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that intraguild predation intensified when remaining aphids clustered on leaf undersides, making them harder to locate. This implies that reduced prey accessibility, not just reduced prey numbers, contributed to the beetles'' shift to consuming each other. The option about beetles being more effective predators than aphids at avoiding consumption introduces an irrelevant comparison not supported by the passage. The option claiming beetles cannot survive without a constant aphid supply goes beyond the evidence, which describes increased cannibalism but not inability to survive. The option suggesting aphids deliberately moved to provoke beetle cannibalism attributes strategic intent to the aphids with no textual support.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HA06Y8', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student wants to explain why the kapok tree''s buttress roots are important. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I71SJG', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geologist Amara Osei has studied sediment cores extracted from Lake Bosumtwi in Ghana to reconstruct West African rainfall patterns over the past 3,000 years. Her data show that prolonged dry periods coincided with declines in the Ghana Empire''s trans-Saharan trade networks during the eleventh and twelfth centuries. Some historians have cited these findings as evidence that climate stress was the principal driver of the empire''s commercial contraction. ______ Osei herself cautions that the sediment record indicates correlation rather than causation, noting that political fragmentation and shifting trade routes also intensified during the same period and may have independently reduced trade volume.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"That is,"},{"key":"C","text":"Moreover,"},{"key":"D","text":"Yet,"}]$lyceon_json$::jsonb, 'D', NULL, E'Historians draw a causal conclusion from Osei''s data, but Osei herself resists that interpretation by emphasizing that correlation does not prove causation and identifying alternative explanations. ''Yet,'' correctly signals that Osei''s cautionary stance pushes back against the historians'' stronger claim. ''By contrast,'' typically introduces an entirely opposing subject or finding rather than a qualification from the same researcher about the same data. ''That is,'' would signal a clarification or restatement of the historians'' position, but Osei is challenging it, not restating it. ''Moreover,'' would add supporting information, whereas Osei''s statement tempers rather than reinforces the historians'' causal claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JFH8BZ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Nutritionist Clara Engstrom argues that fortifying staple grains with micronutrients such as iron and zinc offers the most cost-effective strategy for reducing nutritional deficiencies in low-income populations. She points to large-scale fortification programs in sub-Saharan Africa that have measurably reduced anemia rates among children under five. Text 2: Agricultural scientist Tomasz Krol contends that biofortification, the process of breeding crops to naturally contain higher levels of essential nutrients, provides a more sustainable solution than industrial fortification. Krol notes that once a biofortified variety is developed, farmers can replant it without recurring costs for chemical additives, making it especially practical in regions with limited food-processing infrastructure.', $lyceon_json$[{"key":"A","text":"By arguing that sustainability and independence from processing infrastructure make biofortification preferable to industrial grain fortification"},{"key":"B","text":"By agreeing that industrial fortification is the most effective approach and proposing that biofortification supplement it"},{"key":"C","text":"By questioning whether micronutrient deficiencies are truly a significant public health concern in low-income populations"},{"key":"D","text":"By disputing the accuracy of the anemia-reduction data Engstrom cites from sub-Saharan African programs"}]$lyceon_json$::jsonb, 'A', NULL, E'Text 2''s author, Krol, explicitly advocates biofortification as more sustainable than industrial fortification, citing that biofortified crops eliminate recurring costs for chemical additives and suit regions lacking processing infrastructure. This directly challenges Engstrom''s claim that industrial fortification is the most cost-effective strategy. The option about sustainability and independence from processing infrastructure accurately captures Krol''s likely response. The option about agreeing with industrial fortification contradicts Krol''s position, since he presents biofortification as preferable, not supplementary. The option about questioning whether deficiencies are a significant concern is wrong because Krol addresses how to solve deficiencies, implicitly accepting they are a real problem. The option about disputing anemia-reduction data is wrong because Krol never challenges Engstrom''s evidence; his argument concerns long-term sustainability, not data accuracy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KYF4VA', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, on which point would the authors of Text 1 and Text 2 most likely disagree?', E'Text 1: Cognitive scientist Rafaela Sousa posits that bilingual individuals exhibit enhanced executive function not because managing two languages directly strengthens cognitive control mechanisms, but because the sociolinguistic demands of code-switching, the act of selecting the contextually appropriate language in real time, compel bilinguals to develop heightened sensitivity to pragmatic cues. In Sousa''s model, it is the social monitoring required by code-switching, rather than the mere coexistence of two lexicons, that produces the observed cognitive advantages. Text 2: Psycholinguist Henrik Lindqvist argues that the cognitive advantages observed in bilingual populations stem from the continuous inhibitory effort required to suppress the non-target language during speech production. Lindqvist''s experiments demonstrate that bilinguals activate both languages simultaneously even when speaking in only one, and that the neural mechanisms recruited to resolve this competition overlap substantially with domain-general executive control networks. He maintains that this inhibitory demand alone is sufficient to account for bilingual cognitive advantages, independent of any social or communicative context.', $lyceon_json$[{"key":"A","text":"Whether bilingual individuals demonstrate any measurable cognitive advantages compared to monolingual individuals"},{"key":"B","text":"Whether the mechanism responsible for bilingual cognitive advantages is rooted in social monitoring during communication or in language-internal inhibitory processes"},{"key":"C","text":"Whether bilingual speakers activate both languages simultaneously during speech production in monolingual conversational settings"},{"key":"D","text":"Whether executive function can be meaningfully separated from other cognitive capacities such as working memory and attentional control"}]$lyceon_json$::jsonb, 'B', NULL, E'Text 1''s author attributes bilingual cognitive advantages to social monitoring during code-switching, while Text 2''s author attributes them to language-internal inhibitory suppression, explicitly stating this mechanism operates independent of social context. The core disagreement is about the mechanism, not the existence, of the advantage. The option about whether the mechanism is rooted in social monitoring or inhibitory processes precisely identifies this dispute. The option about whether bilinguals show any cognitive advantages is wrong because both authors accept that bilingual cognitive advantages exist; they disagree only about the cause. The option about whether bilinguals activate both languages simultaneously is wrong because only Lindqvist discusses this finding, and Sousa''s argument does not address or contest dual activation; the disagreement is about what produces the cognitive benefit, not about dual activation itself. The option about whether executive function can be separated from working memory is wrong because neither text addresses this distinction; both treat executive function as an accepted construct.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LUUQHH', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Archaeologists excavating a site near the Tollense River in northeastern Germany uncovered thousands of bronze and flint arrowheads embedded in a narrow river valley, along with the skeletal remains of at least 140 individuals bearing signs of violent trauma. <u>Carbon dating placed the artifacts and remains firmly in the thirteenth century BCE, centuries before any written accounts of organized warfare in northern Europe.</u> This temporal placement has led scholars to reassess longstanding narratives that depicted Bronze Age societies in the region as predominantly pastoral and cooperative, forcing consideration of the possibility that large-scale military conflicts occurred far earlier than textual evidence alone would suggest.', $lyceon_json$[{"key":"A","text":"It provides a temporal context that underpins the scholarly reassessment described afterward."},{"key":"B","text":"It offers a counterexample that weakens the archaeological evidence presented in the preceding sentence."},{"key":"C","text":"It summarizes the central conclusion that the rest of the text is organized to defend at length."},{"key":"D","text":"It introduces an unresolved methodological controversy about the reliability of dating techniques used at the site."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence establishes that the artifacts date to the thirteenth century BCE, predating written records of warfare in northern Europe. This dating is what drives the scholarly reassessment described in the final sentence. The option about providing temporal context that underpins the reassessment accurately describes this function. The option claiming it weakens the archaeological evidence is wrong because the dating actually reinforces the significance of the physical finds, not undermines them. The option stating it summarizes the central conclusion is wrong because the conclusion about reassessing narratives appears in the following sentence, not in the underlined one, which provides supporting evidence. The option about an unresolved methodological controversy is wrong because the passage presents the carbon dating as established fact, not as contested methodology.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M84V2R', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The restoration team not only reinforced the cathedral''s deteriorating buttresses with titanium brackets but also ______ the original limestone facades using a polymer sealant derived from recycled marine algae.', $lyceon_json$[{"key":"A","text":"they preserved"},{"key":"B","text":"preserving"},{"key":"C","text":"preserved"},{"key":"D","text":"had been preserving"}]$lyceon_json$::jsonb, 'C', NULL, E'The correlative conjunction pair "not only...but also" requires parallel structure: the verb form after "but also" must match the form after "not only." Since the first element is "reinforced" (simple past tense verb), the second element must also be a simple past tense verb. "preserved" correctly maintains parallel structure with "reinforced." "they preserved" breaks the parallelism by introducing a new subject pronoun, which disrupts the structure of the single subject ("The restoration team") governing both verbs. "preserving" is a present participle (gerund form) that is not parallel with the past tense "reinforced." "had been preserving" uses the past perfect progressive tense, which is neither parallel with "reinforced" nor appropriate for describing a completed restoration action.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MKD2IE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare mineral specimens that the university acquired from a retired prospector last spring ______ on permanent display in the geology building''s main corridor.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"have been placed"},{"key":"C","text":"is"},{"key":"D","text":"were"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "collection," which is singular, so the verb must also be singular. The intervening prepositional phrase "of rare mineral specimens" and the relative clause "that the university acquired from a retired prospector last spring" do not change the number of the subject. "is" correctly provides a singular present-tense verb agreeing with "collection." "are" is a plural verb that incorrectly agrees with "specimens" rather than the true subject "collection." "have been placed" is plural and also introduces a passive construction that does not fit the context of being "on permanent display." "were" is plural and past tense, failing to agree with the singular subject and conflicting with the present-tense context of the display still being up.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MS35UT', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2019, marine biologist Rana Okafor documented an unusual behavioral shift among loggerhead sea turtles nesting along the coast of Senegal. Okafor observed that the turtles had begun nesting approximately eleven days earlier than the historical average recorded over the previous four decades. She attributed this shift primarily to rising sand temperatures at the nesting sites, which reached the thermal threshold for egg incubation sooner in the season. Okafor noted that while earlier nesting could reduce exposure to late-season storms, it might also increase the risk of egg predation by monitor lizards, whose own activity peaks earlier in the warm months.', $lyceon_json$[{"key":"A","text":"Rising sand temperatures have caused loggerhead sea turtles in Senegal to nest earlier, a change that carries both potential benefits and risks."},{"key":"B","text":"Monitor lizards in Senegal pose a growing threat to sea turtle eggs because warming temperatures have extended the lizards' active season."},{"key":"C","text":"Rana Okafor's four-decade study of loggerhead sea turtles in Senegal has fundamentally changed how marine biologists understand nesting behavior."},{"key":"D","text":"Loggerhead sea turtles nesting in Senegal have developed a new survival strategy to avoid late-season storms by deliberately choosing cooler sand."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Okafor''s observation that loggerhead turtles in Senegal are nesting earlier due to rising sand temperatures and notes that this change has both a potential benefit (reduced storm exposure) and a potential risk (increased egg predation). The option stating that rising sand temperatures caused earlier nesting with both benefits and risks captures this central idea. The option about monitor lizards posing a growing threat distorts the passage, which mentions lizard predation as one risk rather than the central point. The option claiming Okafor''s study fundamentally changed marine biology overstates the passage, which describes a single observational finding. The option about turtles deliberately choosing cooler sand contradicts the passage, which says warmer sand triggered the shift.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NLWDCF', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes data from the study that would weaken the marketing team''s claim?', E'A marketing team at a consumer electronics company claims that customers who participate in the company''s loyalty program make purchases more frequently than non-participants because the program''s point-based rewards motivate repeat buying. To test this claim, an independent research group analyzed purchase records from 8,700 customers over a thirty-month period, comparing loyalty program participants with non-participants matched on income level and initial purchase frequency.', $lyceon_json$[{"key":"A","text":"Loyalty program participants made purchases at the same frequency as matched non-participants throughout the thirty-month study period."},{"key":"B","text":"Customers with higher income levels were more likely to enroll in the loyalty program than customers with lower income levels."},{"key":"C","text":"The loyalty program's point-based reward structure was redesigned twice during the thirty-month study period."},{"key":"D","text":"Non-participants who were surveyed expressed interest in joining the loyalty program if the enrollment process were simplified."}]$lyceon_json$::jsonb, 'A', NULL, E'The marketing team claims that the loyalty program''s rewards motivate more frequent purchases. A finding that participants purchased at the same frequency as matched non-participants would directly contradict this claim by showing no difference in buying behavior between the two groups. The finding about higher-income customers enrolling more often addresses enrollment patterns rather than purchase frequency, so it does not directly weaken the claim about rewards motivating repeat buying. The finding about the reward structure being redesigned introduces a complication but does not show that the program fails to increase purchase frequency. The finding about non-participants wanting to join addresses potential enrollment, not whether the program actually changes buying behavior.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OJWS81', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Literary critic Ananya Mukherjee has observed that the Partition novels of the 1950s, written by authors who had directly experienced the division of British India in 1947, tend to foreground individual trauma through fragmented narrative structures that resist chronological coherence. By contrast, Partition novels published after 2000 by writers born well after the event often adopt more conventional linear plots while embedding collective memory through recurring symbolic motifs such as abandoned trains, severed maps, and empty courtyards. <u>Mukherjee contends that this shift does not represent a diminishment of emotional intensity but rather a migration of grief from the structural plane of narrative form to the semantic plane of figurative language.</u> Her framework thus positions the evolution of Partition literature not as a loss of authenticity but as a transformation in the literary technologies through which communal suffering is encoded.', $lyceon_json$[{"key":"A","text":"It presents Mukherjee's interpretive claim that reframes an apparent decline as a formal transformation, which the final sentence then extends into a broader theoretical position."},{"key":"B","text":"It introduces a concession to critics who argue that later Partition novels lack the raw emotional power of their predecessors."},{"key":"C","text":"It supplies empirical evidence drawn from specific novels to substantiate the contrast outlined in the two preceding sentences."},{"key":"D","text":"It qualifies the distinction between early and later Partition novels by acknowledging that the two categories share certain narrative techniques despite surface-level differences."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents Mukherjee''s argument that the shift from fragmented to linear narrative does not diminish emotional intensity but relocates grief from form to figurative language. The final sentence builds on this by framing the evolution as transformation rather than loss. The option describing an interpretive claim that reframes an apparent decline as a formal transformation, extended by the final sentence, accurately captures this role. The option about a concession to critics is wrong because Mukherjee is not acknowledging that later novels are weaker; she is arguing the opposite, that emotional intensity persists in a different mode. The option about empirical evidence from specific novels is wrong because the underlined sentence offers a theoretical interpretation, not evidence from particular texts. The option about qualifying the distinction by noting shared techniques is wrong because Mukherjee does not claim the two groups share techniques; she argues that grief migrated from one plane to another, maintaining the distinction rather than dissolving it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PEJYQ4', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Architect Elif Sarikaya designed a public library in Ankara whose facade is covered with 1,400 ceramic tiles, each angled slightly differently to reflect sunlight in shifting patterns throughout the day. Sarikaya has stated that she wanted visitors to perceive the building as responsive to its environment rather than as a static object. Architectural critic Dario Voss praised the design but noted that the tiles'' reflective surface can create intense glare for pedestrians on the adjacent sidewalk during certain afternoon hours. Sarikaya acknowledged this drawback and explained that she had considered using matte-finish tiles but ultimately rejected that approach because ________', $lyceon_json$[{"key":"A","text":"matte tiles would have been significantly less expensive to manufacture than the reflective ceramic tiles she selected."},{"key":"B","text":"the shifting light patterns that made the building appear responsive depended on the tiles' capacity to reflect direct sunlight."},{"key":"C","text":"Voss had previously criticized another architect for using matte tiles on a public building in a different Turkish city."},{"key":"D","text":"the Ankara city council required all new public buildings to incorporate reflective surfaces into their exterior designs."}]$lyceon_json$::jsonb, 'B', NULL, E'Sarikaya''s stated goal was to make the building appear responsive to its environment through shifting sunlight patterns. Matte tiles would eliminate glare but would also eliminate the reflective properties that produce those patterns. The option explaining that the shifting light patterns depended on reflective capacity logically completes the text by connecting Sarikaya''s rejection of matte tiles to her core design intent. The option about matte tiles being less expensive contradicts the logic of the passage, since lower cost would be a reason to use them, not reject them. The option about Voss criticizing another architect introduces an unsupported and irrelevant detail. The option about a city council requirement introduces an external mandate with no basis in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QR5S40', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the linguist Fatou Diallo first cataloged the tonal patterns of the Serer language in 2017, she ______ that several pitch contours had no documented equivalent in any other West African dialect studied up to that point.', $lyceon_json$[{"key":"A","text":"has noted"},{"key":"B","text":"noted"},{"key":"C","text":"will have noted"},{"key":"D","text":"notes"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence establishes a past time frame with the clause "When...Diallo first cataloged...in 2017," so the verb in the main clause must be in the simple past tense to match. "noted" correctly provides a simple past verb consistent with the 2017 time frame. "has noted" uses the present perfect tense, which is incompatible with the specific past time marker "in 2017"; present perfect cannot pair with a definite past date. "will have noted" uses the future perfect tense, which is illogical for an event that already occurred in 2017. "notes" uses the present tense, which conflicts with the established past time frame of the sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SEKG71', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, ethnomusicologists categorized the gamelan traditions of Central Java and Bali as regional variants of a single musical system, differing mainly in tuning and instrumentation. This framework rested on the assumption that both traditions descended from a common court music practice that diverged after the fall of the Majapahit Empire in the late fifteenth century. Recently, however, musicologist Ayu Pramesti has challenged this genealogical model. Analyzing melodic contour patterns in over three hundred archival recordings, Pramesti found that Balinese gamelan compositions employ a rhythmic layering principle she calls "nested acceleration" that has no structural parallel in Central Javanese repertoire. Rather than treating this difference as a later innovation, Pramesti argues that nested acceleration reflects an independent compositional logic that predates any contact between the two traditions, suggesting that the assumed common ancestor may itself be a scholarly construction.', $lyceon_json$[{"key":"A","text":"It presents a longstanding scholarly framework, introduces a researcher's challenge to that framework based on specific evidence, and describes the broader implication of her argument."},{"key":"B","text":"It contrasts two musical traditions, explains the historical events that caused them to diverge, and evaluates which tradition more faithfully preserves the original practice."},{"key":"C","text":"It summarizes a musicologist's career-long research program, details three distinct findings from her work, and proposes a new theoretical model she developed from those findings."},{"key":"D","text":"It describes a controversy among ethnomusicologists about Javanese court music, presents arguments from both sides of the debate, and concludes that neither position is fully supported by the evidence."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first describes the longstanding genealogical framework linking Javanese and Balinese gamelan, then introduces Pramesti''s challenge to that framework based on her analysis of melodic contour patterns, and finally presents the broader implication that the assumed common ancestor may be a scholarly construction. The option capturing this three-part structure accurately reflects the passage. The option about contrasting traditions and evaluating which is more faithful misrepresents the passage, which does not evaluate fidelity to an original practice. The option about a career-long research program with three distinct findings overstates the scope; the passage describes one study with one key finding. The option about a controversy with arguments from both sides mischaracterizes the passage, which presents only Pramesti''s challenge to the established view without giving a rebuttal from other scholars.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VPGTMP', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Historian Kenji Watanabe has argued that the rapid adoption of double-entry bookkeeping in fourteenth-century Italian merchant houses was driven less by the method''s computational advantages than by the social trust it conferred. Because double-entry ledgers required every transaction to appear in two separate accounts, they created a verifiable paper trail that could be audited by outside parties. Watanabe contends that merchants who adopted the system were not primarily seeking more accurate records for internal use but were instead signaling to potential trading partners and creditors that their accounts could withstand independent scrutiny. Some economic historians have objected that Watanabe''s argument cannot explain why double-entry bookkeeping was also adopted by family-run firms that traded exclusively within kinship networks, where ________', $lyceon_json$[{"key":"A","text":"the computational advantages of double-entry bookkeeping were well understood by all members of the family."},{"key":"B","text":"the need to signal trustworthiness to outside parties would have been minimal because trading partners already had strong personal ties."},{"key":"C","text":"Italian merchant families in the fourteenth century frequently dissolved their trading partnerships over disputes about bookkeeping methods."},{"key":"D","text":"independent auditors were routinely hired by kinship-based trading networks to verify the accuracy of single-entry ledgers."}]$lyceon_json$::jsonb, 'B', NULL, E'Watanabe''s argument is that double-entry bookkeeping was adopted primarily to signal trustworthiness to outside parties. The objection concerns family-run firms trading within kinship networks. The completion must explain why adoption within these networks is a problem for Watanabe''s thesis. The option noting that the need to signal trustworthiness would have been minimal because partners already had strong personal ties logically completes the objection: if trust already existed through kinship, the signaling motive Watanabe identifies would not apply. The option about computational advantages being well understood shifts to a different explanation rather than completing the stated objection about signaling. The option about families dissolving partnerships over bookkeeping introduces a claim unsupported by and irrelevant to the passage''s argument. The option about auditors being hired for single-entry ledgers introduces a factual claim that contradicts the logic of the passage, which associates auditability with double-entry, not single-entry.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W02N9T', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Historian Priya Venkatesh argues that the decline of the Khmer Empire in the fifteenth century was driven primarily by the deterioration of its elaborate hydraulic infrastructure. Prolonged droughts, she contends, overwhelmed the capacity of the empire''s reservoir and canal system, leading to agricultural failures that eroded the economic base sustaining Angkor''s monumental construction projects and administrative apparatus. Text 2: Archaeologist Daisuke Nakata proposes that the Khmer Empire''s decline was precipitated not by environmental collapse alone but by a deliberate strategic reorientation. Nakata''s excavations at coastal trading sites suggest that Khmer elites gradually redirected resources toward maritime commerce in the Gulf of Siam, abandoning inland agricultural infrastructure not because it failed but because oceanic trade networks offered more lucrative returns.', $lyceon_json$[{"key":"A","text":"Text 2 offers an alternative explanation for the same historical phenomenon that Text 1 attributes to environmental and infrastructural causes."},{"key":"B","text":"Text 2 provides additional archaeological evidence that strengthens the environmental hypothesis presented in Text 1."},{"key":"C","text":"Text 1 presents a broadly accepted consensus, while Text 2 refutes it by proving that the Khmer hydraulic system never existed."},{"key":"D","text":"Text 1 focuses on the construction of Angkor's monuments, while Text 2 focuses on the artistic traditions of the Khmer court during the same period."}]$lyceon_json$::jsonb, 'A', NULL, E'Text 1 attributes the Khmer decline to hydraulic deterioration and drought, while Text 2 proposes a deliberate strategic shift toward maritime commerce as the cause. Both address the same event, the decline of the Khmer Empire, but offer different explanations. The option about Text 2 offering an alternative explanation for the same phenomenon accurately captures this relationship. The option claiming Text 2 strengthens Text 1''s hypothesis is wrong because Nakata explicitly challenges the environmental explanation by arguing the infrastructure was abandoned strategically, not because it failed. The option stating Text 2 refutes Text 1 by proving the hydraulic system never existed is wrong because Nakata does not deny the system existed; he argues it was deliberately abandoned. The option about Text 1 focusing on monument construction and Text 2 on artistic traditions misrepresents both texts; Text 1 discusses agricultural and economic decline, and Text 2 discusses maritime trade reorientation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X3W3XZ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Soil scientists at the University of Manitoba hypothesize that the unusually high crop yields observed in fields adjacent to beaver ponds in northern Alberta result from elevated nitrogen levels in the soil. The scientists propose that decomposing organic matter trapped behind beaver dams releases nitrogen compounds that gradually seep into neighboring agricultural land through subsurface water flow.', $lyceon_json$[{"key":"A","text":"Soil samples taken from fields near beaver ponds contain significantly higher concentrations of nitrogen compounds than samples from comparable fields with no nearby beaver activity."},{"key":"B","text":"Beaver populations in northern Alberta have increased steadily over the past two decades due to conservation efforts by provincial wildlife agencies."},{"key":"C","text":"Farmers in northern Alberta who plant nitrogen-fixing cover crops report higher yields than farmers who leave their fields fallow during the off-season."},{"key":"D","text":"Fields adjacent to beaver ponds in northern Alberta receive approximately the same amount of annual rainfall as fields in other parts of the province."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis is that high crop yields near beaver ponds result from elevated soil nitrogen originating from decomposing matter behind beaver dams. The finding that soil near beaver ponds contains significantly higher nitrogen concentrations than soil without nearby beaver activity would directly support the proposed mechanism linking beaver dams to nitrogen enrichment. The finding about beaver population growth is relevant to beaver activity generally but does not address whether nitrogen levels are elevated near their ponds. The finding about nitrogen-fixing cover crops addresses a different source of nitrogen unrelated to beaver ponds. The finding about equivalent rainfall addresses water availability but not nitrogen content, which is the specific mechanism proposed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XP9I1M', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramicist Jun Hayashi, whose wood-fired kiln operates at temperatures exceeding 1,300 ______ routinely achieves a glaze effect that most potters consider nearly impossible to replicate outside of controlled laboratory conditions.', $lyceon_json$[{"key":"A","text":"degrees; routinely"},{"key":"B","text":"degrees, routinely"},{"key":"C","text":"degrees. Routinely"},{"key":"D","text":"degrees routinely"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence''s main clause is "The ceramicist Jun Hayashi...routinely achieves a glaze effect," with the nonrestrictive clause "whose wood-fired kiln operates at temperatures exceeding 1,300 degrees" set off by commas as a parenthetical. A closing comma after "degrees" is needed to mark the end of this nonrestrictive clause and return to the main clause. "degrees, routinely" correctly provides this closing comma. "degrees; routinely" incorrectly inserts a semicolon in the middle of the main clause, severing the subject from its verb. "degrees. Routinely" places a period that splits the subject ("Jun Hayashi") from its predicate ("routinely achieves"), creating an incomplete sentence before the period and a fragment after it. "degrees routinely" omits the closing comma needed to end the nonrestrictive clause, making the sentence difficult to parse and grammatically incorrect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YOZAKC', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Priya Venkatesh identified a consistent pattern across seventeen Saturniid moth ______ each species exhibited peak flight activity exclusively during intervals when ambient light intensity dropped below a measurable threshold.', $lyceon_json$[{"key":"A","text":"species, each"},{"key":"B","text":"species: each"},{"key":"C","text":"species each"},{"key":"D","text":"species; because each"}]$lyceon_json$::jsonb, 'B', NULL, E'The second clause explains and elaborates on the "consistent pattern" mentioned in the first clause, making a colon the appropriate punctuation mark. "species: each" correctly uses a colon to introduce an explanation of the pattern Venkatesh identified. "species, each" creates a comma splice by joining two independent clauses with only a comma. "species each" is a run-on sentence lacking any punctuation between two independent clauses. "species; because each" incorrectly places a semicolon before "because," which introduces a dependent clause; semicolons should join independent clauses, not set off dependent ones.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YS41GU', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Kenji Watanabe has documented the feeding habits of the pygmy seahorse in coral reef ecosystems near Sulawesi, Indonesia. His observations reveal that the pygmy seahorse relies almost exclusively on tiny crustaceans called copepods for nutrition. ______ when copepod populations decline due to rising water temperatures, pygmy seahorse populations in the affected reefs decline as well.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Alternatively,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence establishes the seahorse''s dependence on copepods, and the final sentence describes the consequence of copepod decline. ''Accordingly,'' correctly signals that the seahorse population decline follows as a logical result. ''Specifically,'' would introduce a narrowing detail rather than a consequence. ''Nevertheless,'' would signal a contrast, but the final sentence is consistent with rather than contrary to the preceding claim. ''Alternatively,'' would introduce a different possibility, which does not fit the cause-and-effect relationship here.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZLKVT9', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geochemist Amara Osei analyzed sediment cores extracted from the floor of Lake ______ the data revealed that phosphorus concentrations had climbed steadily over the preceding nine decades.', $lyceon_json$[{"key":"A","text":"Turkana, the"},{"key":"B","text":"Turkana the"},{"key":"C","text":"Turkana; and the"},{"key":"D","text":"Turkana. The"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage contains two independent clauses: one about Osei analyzing sediment cores and one about what the data revealed. "Turkana. The" correctly separates these independent clauses with a period, forming two grammatically complete sentences. "Turkana, the" creates a comma splice, joining two independent clauses with only a comma and no coordinating conjunction. "Turkana the" produces a run-on sentence with no punctuation between the clauses. "Turkana; and the" pairs a semicolon with the coordinating conjunction "and," which is non-standard; a semicolon alone or a comma with "and" would each be acceptable, but combining the two is not.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZZS3JP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if true, would most directly undermine Petrov''s explanation while being consistent with the observed correlation between canopy density and fungal diversity?', E'Forest ecologist Sasha Petrov has proposed that the strong positive correlation between tree canopy density and below-ground fungal diversity in temperate forests is driven by root exudates: denser canopies indicate more trees, which collectively release a greater volume and variety of carbon-rich root exudates that sustain a wider range of mycorrhizal fungi. However, a competing explanation holds that canopy density affects fungal diversity indirectly, by regulating the moisture and temperature conditions of the forest floor rather than through root chemistry.', $lyceon_json$[{"key":"A","text":"Forests where root exudate composition was artificially held constant still showed a strong positive correlation between canopy density and fungal diversity."},{"key":"B","text":"Fungal diversity in temperate forests is generally higher in regions that receive more annual precipitation, regardless of canopy density."},{"key":"C","text":"Tree species that produce a particularly wide variety of root exudates tend to form denser canopies than species with simpler exudate profiles."},{"key":"D","text":"Below-ground fungal diversity decreases sharply when canopy density is reduced by selective logging, even when the remaining trees are healthy."}]$lyceon_json$::jsonb, 'A', NULL, E'Petrov''s explanation is that root exudates drive the correlation between canopy density and fungal diversity. A finding that the correlation persists even when root exudate composition is held constant would directly undermine the exudate mechanism while preserving the observed correlation, which is consistent with the competing explanation involving moisture and temperature regulation. The finding about precipitation and fungal diversity addresses a different variable (rainfall) without testing the exudate mechanism or maintaining the canopy-density correlation. The finding about exudate-rich species forming denser canopies would actually support Petrov''s explanation by linking exudate variety to canopy density. The finding about fungal diversity declining after selective logging is consistent with both Petrov''s explanation and the competing one, since removing trees reduces both root exudates and canopy-regulated floor conditions, so it does not distinguish between the two.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
